private static void tryNameMatching(final Set<SubRuleContext> candidateSubRuleIds, final NameState nameState, final Task task, final int keyIndex, final SubRuleContext.Generator subRuleContextGenerator) {
    if (!nameState.hasKeyTransitions()) {
        return;
    }
    for (NameState nextNameState : nameState.getNameTransitions(task.event)) {
        if (nextNameState != null) {
            addNameState(candidateSubRuleIds, nextNameState, ABSENCE_PATTERN, task, keyIndex, subRuleContextGenerator);
        }
    }
}
